using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class GiosuèCarducci
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Colui che potendo dire una cosa in dieci parole ne impiega dodici, io lo ritengo capace delle peggiori azioni.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "l'arte e la letteratura sono l'emanazione morale della civiltà, la spirituale irradiazione dei popoli.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Non rampare di aquile e leoni, non sormontare di belve rapaci, nel santo vessillo; ma i colori della nostra primavera e del nostro paese, dal Cenisio all'Etna; le nevi delle Alpi, l'aprile delle valli, le fiamme dei vulcani.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Non sa ella, signora Contessa, che Domineddio fece apposta il Lambrusco per annaffiare la carne dell'animale fausto ad Enea e caro ad Antonio abbate? E io, per glorificare Dio e benedire la sua provvidenza, mi fermai a Modena a lungo a meditare la Sapienza.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Pastonchi? mai letto tanti brutti versi.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Qui il paese è veramente bello, tale che fa intendere la Scuola umbra: che linee d'orizzonte, che digradante vaporoso di monti in lontananza! Fui ad Assisi: è una gran bella cosa, paese, città e santuario, per chi intende la natura e l'arte nei loro accordi con la storia, con la fantasia con gli affetti degli uomini.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Ai giudizi dei nemici vuolsi avere sempre la debita osservanza.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "È pure un vil facchinaggio quello di dovere o volere andar d'accordo co' molti!", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "I giovini non possono generalmente esser critici; e, per due o tre che riescano, cento lasciano ai rovi della via i brandelli del loro ingegno o ne vengon fuori tutti inzaccherati di pedanteria e tutti irti le vesti di pugnitopi: la critica è per gli anni maturi.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "la repubblica, per me, è l'esplicazione storica e necessaria e l'assettamento morale della democrazia ne' suoi termini razionali: la repubblica, per me è il portato logico dell'umanesimo che pervade ormai tutte le istituzioni sociali.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "L'arte, come la concepisco e come non arrivo a farla io, è cosa altamente e perfettamente [...] aristocratica.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Riprendemmo Roma al papa, riprenderemo Trieste all'imperatore. A questo imperatore degl'impiccati.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Ed allora per tutto il parlamento trascorse quasi un fremito di belve.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Venne il dì nostro (o milanesi), e vincere bisogna.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Maledetta sii tu, mia patria antica, su cui l'onta de l'oggi e la vendetta de i secoli s'abbica!", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "La nostra patria è vile.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Impronta Italia domandava Roma, Bisanzio essi le han dato.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "E un popol morto dietro a lui si mise. Esule antico, al ciel mite e severo leva ora il volto che giammai non rise, — tu sol — pensando — o idëal, sei vero.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Ma voi siete cristiane, o Maddalene! Foste da' preti a scuola. Siete moderne! avete ne le vene l'Aretino e il Loiola", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "E il sol nel radiante azzurro immenso fin de gli Abruzzi al biancheggiar lontano folgora, e con desio d'amor più intenso ride a' monti de l'Umbria e al verde piano", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Da le vie, da le piazze gloriose, ove, come dal maggio ilare a i dì boschi di querce e cespiti di rose, la libera de' padri arte fiorì';", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Lieta del fato Brescia raccoltemi, Brescia la forte, Brescia la ferrea, Brescia leonessa d'Italia beverata nel sangue nemico.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Salve, Umbria verde, e tu del puro fonte nume Clitumno!", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Roma, ne l'aer tuo lancio l'anima altera volante: accogli, o Roma, e avvolgi l'anima mia di luce", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Anch'ei, tra 'l dubbio giorno d'un gotico tempio avvolgendosi, l'Alighier trepido cercò l'immagine di Dio nel gemmeo pallore d'una femina", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Surge nel chiaro inverno la fosca turrita Bologna, e il colle di sopra bianco di neve ride", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "quando Odoacre dinanzi a l'impeto di Teodorico cesse, e tra l'èrulo eccidio passavan sui carri dritte e bionde le donne amàle || entro la bella Verona, odinici carmi intonando: raccolta al vescovo intorno, l'italica plebe sporgea la croce supplice a' Goti", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "una gran tazza argentea, || cui placido olivo per gli orli nitidi corre misto a l'eterno lauro.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Breve ne l'onda placida avanzasi striscia di sassi. Boschi di lauro frondeggiano dietro spirando effluvi e murmuri ne la sera. | Par che da questo nido pacifico in picciol legno l'uom debba movere secreto a colloqui d'amore leni su zefiri, la sua donna fisa guatando l'astro di Venere.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Superba ardeva di lumi e cantici nel mar morenti lontano Genova al vespro lunare dal suo | arco marmoreo di palagi.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Fulgida e bionda ne l'adamantina luce del serto tu passi", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Già il mostro, conscio di sua metallica anima, sbuffa, crolla, ansa, i fiammei occhi sbarra; immane pe 'l buio gitta il fischio che sfida lo spazio.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Oh qual caduta di foglie, gelida, continua, muta, greve, su l'anima! io credo che solo, che eterno, che per tutto nel mondo è novembre.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Quale una incinta, su cui scende languida languida l'ombra del sopore e l'occupa, disciolta giace e palpita su 'l talamo, sospiri al labbro e rotti accenti vengono e súbiti rossor la faccia corrono || [...] Chinatevi al lavoro, o validi omeri; schiudetevi agli amori, o cuori giovani; impennatevi a sogni, ali dell'anime; irrompete alla guerra, o desii torbidi: ciò che fu torna e tornerà nei secoli", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "L'ora presente è in vano, non fa che percuotere e fugge, sol nel passato è il bello, sol ne la morte è il vero.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Ah, ma non ivi alcuno de' novi poeti mai surse, se non tu forse, Shelley, spirito di titano, entro virginee forme", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Contessa, che è mai la vita? È l'ombra d'un sogno fuggente. La favola breve è finita, il vero immortale è l'amor.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Salve, Piemonte! A te con melodia mesta, da lungi risonante, come gli epici canti del tuo popol bravo, scendono i fiumi. Scendono pieni, rapidi, gagliardi, come i tuoi cento battaglioni, e a valle cercan le deste a ragionar di gloria ville e cittadi", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "e da Superga nel festante coro de le grandi Alpi la regal Torino incoronata di vittoria, ed Asti repubblicana", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Italia assunta novella tra le genti", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "A te, porgente su l'argenteo Sile le braccia a l'avo da l'opima cuna, ne la festante ilarità senile parve la vita accorrere con una || marïonetta in mano. Al sol d'aprile te fuggente la logica importuna presago accolse il comico navile veleggiando la tacita laguna", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Seco venga a' lidi tuoi fe' d'opre alte e leggiadre, o isola del sole, o tu d'eroi Sicilia antica madre.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "come, o Ferrara, bello ne la splendida ora d'Aprile ama il memore sole la tua pace!", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Salve, Ferrara, co'l tuo fato in pugno ultima nata, creatura nova de l'Appennin, del Po, del faticoso dolore umano!", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Ombra d'un fiore è la beltà, su cui bianca farfalla poesia volteggia: eco di tromba che si perde a valle è la potenza.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Fuga di tempi e barbari silenzi vince e dal flutto de le cose emerge sola, di luce a 'i secoli affluenti faro, l'idea.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Ave, o rima! Con bell'arte su le carte te persegue il trovadore; ma tu brilli, tu scintilli, tu zampilli su del popolo dal cuore. O scoccata tra due baci ne i rapaci volgimenti de la danza, come accordi ne' due giri due sospiri, di memoria e di speranza!", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Pur ne l'ombra de' tuoi lati velami gli umani tedi, o notte, ed i miei bassi crucci ravvolgi e sperdi: a te mi chiami, e con te sola il mio cuor solo stassi.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Te che solinghe balze e mèsti piani ombri, o quercia pensosa, io più non amo, poi che cedesti al capo de gl'insani eversor di cittadi il mite ramo.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Né te, lauro infecondo, ammiro o bramo, che mènti e insulti, o che i tuoi verdi e strani orgogli accampi in mezzo al verno gramo o in fronte a calvi imperador romani.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Amo te, vigna, che tra bruni sassi pampinea ridi, ed a me pia maturi il sapïente de la vita oblio.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Ma più onoro l'abete: ei fra quattr'assi, nitida bara, chiuda al fin li oscuri del mio pensier tumulti e il van desio.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "T'amo, o pio bove; e mite un sentimento di vigore e di pace al cor m'infondi. O che solenne come un monumento tu guardi i campi liberi e fecondi, o che al giogo inchinandoti contento l'agil opra de l'uom grave secondi:", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Il divino del pian silenzio verde", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Meglio cosí; ch'io non mi vegga avanti gli academici Lapi e i Bindi artieri: Io vo' vedere il cavalier de' santi, il santo io vo' veder de' cavalieri.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Dante, onde avvien che i vóti e la favella levo adorando al tuo fier simulacro, e me sul verso che ti fè già macro lascia il sol, trova ancor l'alba novella?", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "L'albero a cui tendevi la pargoletta mano, il verde melograno da' bei vermigli fior, nel muto orto solingo rinverdì tutto or ora e giugno lo ristora di luce e di calor.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Tu fior de la mia pianta percossa e inaridita, tu de l'inutil vita estremo unico fior, sei ne la terra fredda, sei ne la terra negra; né il sol più ti rallegra né ti risveglia amor.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Maggio risveglia i nidi, maggio risveglia i cuori; porta le ortiche e i fiori, i serpi e l'usignol.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "La nebbia agl'irti colli piovigginando sale, e sotto il maestrale urla e biancheggia il mar; ma per le vie del borgo dal ribollir de' tini va l'aspro odor de i vini l'anime a rallegrar.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Sai tu l'isola bella, a le cui rive manda il Ionio i fragranti ultimi baci nel cui sereno mar Galatea vive e su' monti Aci?", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "De l'ombroso pelasgo Èrice in vetta eterna ride ivi Afrodite e impera, e freme tutt' amor la benedetta da lei costiera", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Meglio operando oblïar, senza indagarlo; questo enorme mister de l'universo!", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Odio la faccia tua stupida e tonda, l'inamidata cotta, monacella lasciva ed infeconda, celeste paölotta", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Si volse il prete a dire: Ite. Potente ruppe il sole a le nubi sormontando, e incoronò d'un'iride scendente la bella donna che sorgea pregando.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "I cipressi che a Bólgheri alti e schietti van da San Guido in duplice filar, quasi in corsa giganti giovinetti mi balzarono incontro e mi guardâr.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Su 'l castello di Verona batte il sole a mezzogiorno da la Chiusa al pian rintrona solitario un suon di corno,", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Sanguinosa, in un sorriso di martirio e di splendor: di Boezio è il santo viso, del romano senator.", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "o noci della Carnia addio! Erra tra i vostri rami il pensier mio sognando l'ombre d'un tempo che fu!", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Cittadini di palagio, mercanti e buon artieri; e voi conti di maremma, dai selvatici manieri; voi di Corsica visconti, voi marchesi de' confini; voi che re siete in Sardegna ed in Pisa cittadini;", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Hallali, hallali, gente d'Habsburgo! Ad una caccia eterna io con te surgo;", Author = "Giosuè Carducci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giosuè_Carducci", Text = "Poeta, su 'l tuo capo sospeso ho il tricolore che da le spiagge d'Istria da l'acque di Salvore la fedele di Roma, Trieste, mi mandò", Author = "Giosuè Carducci" },
        };
    }
}